TIER = {"core": ("Core", "Everyone builds this"), "stretch": ("Stretch", "If there is time"), "instructor": ("Instructor", "Demonstrated, not built")}


def read(p):
    with open(p, encoding="utf-8") as fh:
        return fh.read()


def figure(fig_id, prefix, title, desc_lines):
    path = os.path.join(FIG, fig_id + ".svg")
    if not os.path.exists(path):
        return f'<p class="muted">Figure {html.escape(fig_id)} is not generated yet.</p>'
    svg = namespace_svg(read(path), prefix)
    # accessibility: name and describe the drawing; the reading list repeats it in words
    tid, did = f"{prefix}title", f"{prefix}desc"
    svg = svg.replace("<svg", f'<svg role="img" aria-labelledby="{tid} {did}"', 1)
    svg = svg.replace(">", f'><title id="{tid}">{html.escape(title)}</title><desc id="{did}">{html.escape(" ".join(desc_lines))}</desc>', 1)
    svg = svg.replace("<title>", "<title hidden>", 1) if svg.count("<title") > 1 else svg
    return svg



def concept_block(mod_id, prefix):
    items = MODULE_VISUALS.get(mod_id, [])
    if not items:
        return ""
    cards = []
    for i, (vid, _, title, caption) in enumerate(items):
        path = os.path.join(VIS, vid + ".svg")
        if not os.path.exists(path):
            continue
        svg = namespace_svg(read(path), f"{prefix}v{i}-")
        cards.append(f'<figure class="concept"><h4>{html.escape(title)}</h4><div class="sheet">{svg}</div><figcaption>{html.escape(caption)}</figcaption></figure>')
    return '<div class="concepts"><h3>The ideas, one picture each</h3>' + "".join(cards) + "</div>"


